INSERT INTO `team_members` (`name`, `role`, `group_name`, `summary`, `full_info`, `image`, `order_index`) VALUES
('Prof. Julia Ojiambo', 'CBS, EBS, MBS', 'Advisory Council', 'A pioneering Kenyan leader and the first Black African woman appointed as a Lecturer at the University of Nairobi’s College of Health Sciences.', 'She later earned her PhD there and became Kenya’s first female Cabinet Member. In 1976, she received the FAO Ceres Gold Medal for advancing socioeconomic empowerment for rural youth and women. She has also been honored with the President’s Awards of the Order of the Burning Spear (MBS, EBS, and CBS) for her distinguished public service and leadership in the Labour Party of Kenya.', '', 1),
('Ms Betty Adera', 'Global Health Leader', 'Advisory Council', 'A dynamic global health leader with over 20 years of experience driving impactful programs across Africa.', 'A public health expert with strong credentials (MPH, PMD, PGMD) and a PhD candidate, she brings a proven record in strategic leadership, health systems strengthening, policy advocacy, and program management.', '', 2),
('Mr. Michael Ager', 'Global Consultant', 'Advisory Council', 'Global Consultant in Public Relations, Governance, and Advocacy.', 'He is a passionate, results-driven expert with over a decade of experience collaborating with government agencies (Kenya’s Ministry of Labour), UN bodies (UNDP, UNAIDS), and NGOs across national, regional, and international levels.', '', 3),
('Ms Lucy Mworia', 'HSC - CEO & Founder', 'Advisory Council', 'CEO & Founder of the Kenya Pro-Ageing organization, seconded to the Ministry of Health’s Department of Public Health.', 'She serves as a key liaison between the Ministry and implementing partners, strengthening coordination in program planning. Previously with the Ministry of Foreign and Diaspora Affairs, she brings diplomatic expertise to advocacy and partnership building. Through the Kenya Pro-Ageing Organization, she champions initiatives improving the welfare, health, and social inclusion of older persons in Kenya.', '', 4),
('Mr Bruce Tushabe', 'Regional Training Lead', 'Advisory Council', 'A Ugandan national with over 20 years of global development experience, leading Capacity Strengthening at ARASA.', 'A public health advocate and activist, he has supported governments and civil society across East and Southern Africa to advance HIV, TB, and sexual and reproductive health programs.', '', 5),
('Mr. Shem Otina', 'Operations Manager', 'Management Team', 'The Lead Creative and Communications professional guiding the magazine’s storytelling vision and creative direction.', 'He develops people-centered narratives that highlight transformative African voices and translates complex social issues into engaging, accessible content while overseeing editorial consistency, brand identity, and multimedia storytelling.', '', 6),
('Ms Namiso Nafundo', 'Creative and Brand Lead', 'Management Team', 'Lead Journalist driving impactful storytelling that highlights accountability, social issues, and community change.', 'She is a communications specialist with a distinct passion for sports journalism, leveraging her platform to elevate grassroots voices.', '', 7),
('Hon. Fred Sadia', 'Global Partnerships Strategist', 'Management Team', 'A distinguished global strategist connecting grassroots movements with international policy frameworks.', 'He works to advance volunteerism as a professionally managed tool for peacebuilding and sustainable development. Through strategic collaborations and cross-sector partnerships, he strengthens community-driven initiatives to align them with global priorities.', '', 8),
('Moses Abuya', 'Lead Software Engineer', 'Management Team', 'The primary architect behind the magazine\'s digital framework and seamless online experience.', 'Moses developed the Turning Point Magazine platform from scratch utilizing HTML, PHP, JavaScript, CSS, and SQL. A passionate web and Android developer, he bridges complex logic with clean user interfaces, ensuring the platform runs reliably to support the magazine\'s vision across Africa.', '', 9);
